import React, { useEffect, useState } from "react";

export default function AdminWithdrawRequests({ onCancel }) {
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");
  const token = localStorage.getItem("authToken");

  useEffect(() => {
    fetchAllRequests();
  }, []);

  const fetchAllRequests = async () => {
    setLoading(true);
    setMessage("");

    try {
      const res = await fetch("http://localhost:8080/api/withdraw/all", {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      if (!res.ok) {
        throw new Error(`Failed to fetch: ${res.status}`);
      }

      const data = await res.json();
      setRequests(data);
    } catch (err) {
      console.error("Error fetching withdraw requests:", err);
      setMessage("Failed to load withdraw requests.");
    } finally {
      setLoading(false);
    }
  };

  const handleAction = async (id, action) => {
    setMessage("");

    try {
      const res = await fetch(
        `http://localhost:8080/api/withdraw/${action}/${id}`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }
      );

      if (!res.ok) {
        const errorText = await res.text();
        throw new Error(`Failed: ${res.status} ${errorText}`);
      }

      setMessage(`Request ${action}d successfully.`);
      fetchAllRequests();
    } catch (err) {
      console.error(`Error on ${action}:`, err);
      setMessage(`Failed to ${action} request: ${err.message}`);
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case "PENDING":
        return "#ffc107";
      case "APPROVED":
        return "#007bff";
      case "REJECTED":
        return "#dc3545";
      case "COMPLETED":
        return "#28a745";
      default:
        return "#6c757d";
    }
  };

  return (
    <div style={styles.container}>
      <h2 style={styles.title}>📤 সকল উইথড্র রিকোয়েস্ট</h2>

      <button onClick={onCancel} style={styles.backBtn}>
        ⬅️ হোমে ফিরে যান
      </button>

      {message && (
        <div
          style={{
            margin: "20px 0",
            padding: "12px",
            borderRadius: "5px",
            backgroundColor: message.includes("Failed") ? "#f8d7da" : "#d4edda",
            color: message.includes("Failed") ? "#721c24" : "#155724",
            fontWeight: "600",
          }}
        >
          {message}
        </div>
      )}

      {loading ? (
        <p>লোড হচ্ছে...</p>
      ) : requests.length === 0 ? (
        <p>কোনো রিকোয়েস্ট পাওয়া যায়নি।</p>
      ) : (
        <div style={styles.tableWrapper}>
          <table style={styles.table}>
            <thead>
              <tr>
                <th>ID</th>
                <th>Email</th>
                <th>Amount</th>
                <th>Method</th>
                <th>Txn ID</th>
                <th>Receiver</th>
                <th>Status</th>
                <th>Date</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {requests.map((req, index) => (
                <tr key={req.id} style={index % 2 === 0 ? styles.evenRow : styles.oddRow}>
                  <td>{req.id}</td>
                  <td style={{ color: "#ff9900", fontWeight: 500 }}>{req.user?.email || "N/A"}</td>
                  <td>৳ {Number(req.amount).toFixed(2)}</td>
                  <td>{req.method}</td>
                  <td>{req.transactionId}</td>
                  <td>{req.receiverNumber}</td>
                  <td>
                    <span
                      style={{
                        backgroundColor: getStatusColor(req.status),
                        color: "white",
                        padding: "5px 10px",
                        borderRadius: "15px",
                        fontSize: "12px",
                        fontWeight: "bold",
                      }}
                    >
                      {req.status}
                    </span>
                  </td>
                  <td>{new Date(req.requestedAt).toLocaleString()}</td>
                  <td>
                    {req.status === "PENDING" && (
                      <>
                        <button
                          style={{ ...styles.actionBtn, backgroundColor: "#28a745" }}
                          onClick={() => handleAction(req.id, "approve")}
                        >
                          Approve
                        </button>
                        <button
                          style={{ ...styles.actionBtn, backgroundColor: "#dc3545" }}
                          onClick={() => handleAction(req.id, "reject")}
                        >
                          Reject
                        </button>
                      </>
                    )}
                    {req.status === "APPROVED" && (
                      <button
                        style={{ ...styles.actionBtn, backgroundColor: "#17a2b8" }}
                        onClick={() => handleAction(req.id, "complete")}
                      >
                        Complete
                      </button>
                    )}
                    {(req.status === "REJECTED" || req.status === "COMPLETED") && (
                      <span style={{ fontSize: "12px", color: "#6c757d" }}>✔ Done</span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

const styles = {
  container: {
    maxWidth: "100%",
    padding: "30px",
    fontFamily: "Arial, sans-serif",
  },
  title: {
    textAlign: "center",
    fontSize: "24px",
    marginBottom: "20px",
    color: "#333",
  },
  backBtn: {
    backgroundColor: "#007bff",
    color: "white",
    padding: "10px 18px",
    border: "none",
    borderRadius: "6px",
    fontWeight: "600",
    marginBottom: "20px",
    cursor: "pointer",
  },
  tableWrapper: {
    overflowX: "auto",
    borderRadius: "6px",
    border: "1px solid #dee2e6",
  },
  table: {
    width: "100%",
    borderCollapse: "collapse",
    minWidth: "1200px",
  },
  evenRow: {
    backgroundColor: "#f8f9fa",
  },
  oddRow: {
    backgroundColor: "#ffffff",
  },
  actionBtn: {
    margin: "2px",
    padding: "6px 12px",
    border: "none",
    borderRadius: "4px",
    color: "white",
    fontWeight: "600",
    fontSize: "12px",
    cursor: "pointer",
  },
};
